<script setup lang="ts">
import {onMounted} from 'vue';
import {t,formatAmount} from '@kuaixie/i18n';
import type {ApiClient} from '@kuaixie/sdk';
import {useSavedCommerce,type SavedKind} from './useSavedCommerce';
const props=defineProps<{client:ApiClient;kind:SavedKind}>();const p=useSavedCommerce(props.client,props.kind,async()=>window.confirm(t('saved.confirmRemove')));
onMounted(()=>{void p.load()});
</script>
<template><section class="business-card"><h2>{{$t(kind==='addresses'?'migration.address':kind==='cart'?'migration.cart':'migration.favorites')}}</h2><p v-if="p.error.value" role="alert">{{p.error.value}}</p><button :disabled="p.busy.value" @click="p.load(false)">{{$t('common.retry')}}</button>
 <template v-if="kind==='addresses'"><form @submit.prevent="p.save"><label>{{$t('v15.receiver')}}<input v-model="p.draft.value.contactName" maxlength="64" required/></label><label>{{$t('v15.phoneContact')}}<input v-model="p.draft.value.contactPhone" maxlength="32" required/></label><label>{{$t('saved.province')}}<input v-model="p.draft.value.province" maxlength="64"/></label><label>{{$t('account.city')}}<input v-model="p.draft.value.city" maxlength="64"/></label><label>{{$t('saved.district')}}<input v-model="p.draft.value.district" maxlength="64"/></label><label>{{$t('v15.address')}}<textarea v-model="p.draft.value.detail" maxlength="512" required/></label><label><input v-model="p.draft.value.isDefault" type="checkbox"/>{{$t('saved.default')}}</label><button :disabled="p.busy.value">{{$t('account.save')}}</button><button v-if="p.editing.value" type="button" @click="p.reset">{{$t('product.cancel')}}</button></form><article v-for="row in p.addresses.value" :key="row.id" class="business-item"><strong>{{row.contact_name}} · {{row.contact_phone}}</strong><p>{{row.province}} {{row.city}} {{row.district}} {{row.detail}}</p><small v-if="row.is_default">{{$t('saved.default')}}</small><nav class="business-tabs"><button :disabled="p.busy.value" @click="p.edit(row)">{{$t('product.edit')}}</button><button :disabled="p.busy.value" @click="p.remove(row.id)">{{$t('saved.remove')}}</button></nav></article></template>
 <template v-else-if="kind==='cart'"><p>{{$t('saved.cartNotice')}}</p><article v-for="row in p.cart.value" :key="row.id" class="business-item"><a :href="'#services/product-detail?id='+encodeURIComponent(row.product_id)"><strong>{{row.name||$t('saved.unavailable')}}</strong></a><p>{{formatAmount(row.price,'CNY')}} · {{$t(row.available?'product.on':'saved.unavailable')}}</p><input :value="row.qty" type="number" min="1" max="10000" :disabled="p.busy.value||!row.available" @change="p.quantity(row,($event.target as HTMLInputElement).value)"/><button :disabled="p.busy.value" @click="p.remove(row.product_id)">{{$t('saved.remove')}}</button></article></template>
 <template v-else><article v-for="row in p.favorites.value" :key="row.id" class="business-item"><a v-if="row.title" :href="row.target_type==='product'?'#services/product-detail?id='+encodeURIComponent(row.target_id):'#community'">{{row.title}}</a><strong v-else>{{$t('saved.unavailable')}}</strong><button :disabled="p.busy.value" @click="p.remove(row.target_id,row.target_type)">{{$t('saved.remove')}}</button></article></template>
 <button v-if="p.more.value" :disabled="p.busy.value" @click="p.load(true)">{{$t('account.more')}}</button></section></template>
